-- 049_field_crop_chemical_plan_from_file.sql
-- แถบ "ปุ๋ยเคมี" (straight) ของพืชไร่ ข้าว ผัก 20 ชนิด เปลี่ยนจากตารางกรมฯ เป็นค่าในไฟล์
--   "คำนวนปุ๋ยพืชไร่และผัก ไม่ตามกรม 20.11.69_.xlsx" ส่วน 100% (ผู้ใช้เลือก 2026-11-24 ให้ตรงกับไฟล์)
--   วิธีของไฟล์: 18-46-0 = P2O5/0.46, 0-0-60 = K2O/0.6, ยูเรีย = (N - N จาก 18-46-0)/0.46
--     ยูเรียแบ่งครั้งละครึ่ง · 18-46-0 ใส่ครั้งที่ 1 · 0-0-60 ใส่ครั้งที่ 1
--     (พริก มะเขือ มะเขือเทศ กระเจี๊ยบเขียว หน่อไม้ฝรั่ง แบ่ง 0-0-60 ครึ่ง) · มันสำปะหลัง/ถั่ว ใส่ครั้งเดียว
--     ปัดเป็นจำนวนเต็มตามที่ไฟล์แสดง — ค่าทุกช่องตรงกับที่คำนวณซ้ำ และอัตรา N/P2O5/K2O ตรงกับ fertilizer_recommendations
--   ต่างจากตารางกรมฯ เดิม:
--     - กรมฯ แบ่ง "ธาตุ N" ครึ่ง-ครึ่ง (นับ N จาก 18-46-0 ในครั้งที่ 1) ไฟล์แบ่ง "ปริมาณยูเรีย" ครึ่ง-ครึ่ง
--     - กระเทียม หอมแดง หอมหัวใหญ่ ใช้ 46-0-0 แทน 21-0-0 (ตามไฟล์ เหมือนแถบอินทรีย์)
--     - หน่อไม้ฝรั่ง ระยะพักต้นครั้งที่ 2 เป็น 46-0-0 25 (เดิม 0-0-60 25) ตามไฟล์ เหมือนแถบอินทรีย์ (048)
--     - มันสำปะหลัง ข้าวโพดฝักสด ถั่ว ตารางเดิมให้ธาตุรวมไม่ตรงกับอัตราแนะนำ ไฟล์ตรง
--   อ้อย OM < 0.75 ใช้กรณีปกติ (N 27) เหมือน 047 · ถั่ว ทางเลือก "ใช้ไรโซเบียม" = ชุดเดียวกันไม่ใส่ 46-0-0
--   ช่วงค่าดิน ชื่อระยะ หน่วย ใช้ของตารางเดิม — ตารางปุ๋ยผสม (compound เช่น 16-16-8) ไม่เปลี่ยน
--   1842 แถว · รันซ้ำได้

delete from public.crop_fertilizer_plan p
 using public.crops c
 where p.crop_id = c.id and p.use_type = 'straight'
   and trim(c.name) in ('อ้อยปลูก', 'อ้อยตอ', 'มันสำปะหลัง', 'ข้าวโพดเลี้ยงสัตว์', 'ข้าวโพดฝักสด', 'ถั่ว', 'ข้าวไวแสง', 'ข้าวไม่ไวแสง', 'หน่อไม้ฝรั่ง', 'มันฝรั่ง', 'มันเทศ', 'เผือก', 'กระเทียม', 'หอมแดง', 'หอมหัวใหญ่', 'พริก', 'มะเขือ', 'มะเขือเทศ', 'กระเจี๊ยบเขียว', 'ผัก');

